from sage.all_cmdline import *   # import sage library

_sage_const_0p01 = RealNumber('0.01'); _sage_const_0p05 = RealNumber('0.05'); _sage_const_0p2 = RealNumber('0.2'); _sage_const_0p7 = RealNumber('0.7'); _sage_const_1p5 = RealNumber('1.5'); _sage_const_3p0 = RealNumber('3.0'); _sage_const_1p0 = RealNumber('1.0'); _sage_const_2 = Integer(2); _sage_const_0p0 = RealNumber('0.0')# ---------------------------------------------------------
# 双対関係  s_2^* = 1/s_2,  c_2^* = c_2/s_2,  c_2^* = s_2^* c_2
# 対象: structured-latex `duality_c2_star_eq_s2_star_c2`
#
# K_2^* := -(1/2) log(tanh K_2) という定義（<def_transfer_matrix_symbols>）から出発して、
# 上の 3 つの関係を確かめる。単に定義を代入し直すだけでは同語反復なので、
# 右辺は K_2 だけの初等関数（1/sinh 2K_2, coth 2K_2）として独立に評価する。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))
load(os.path.join(_dir, '_prelude.sage'))

rep = CheckReport("duality_c2_star_eq_s2_star_c2: s_2^* = 1/s_2, c_2^* = c_2/s_2, c_2^* = s_2^* c_2")

K2_list = sorted(set([p['K2'] for p in OP_TEST_PARAMS]
                     + CRIT_K2_LIST
                     + [_sage_const_0p01 , _sage_const_0p05 , _sage_const_0p2 , _sage_const_0p7 , _sage_const_1p5 , _sage_const_3p0 ]))

for K2 in K2_list:
    K2s = K_star(K2)                 # -(1/2) log(tanh K_2)
    c2, s2 = c_of(K2), s_of(K2)      # cosh 2K_2, sinh 2K_2
    c2s, s2s = c_of(K2s), s_of(K2s)  # cosh 2K_2^*, sinh 2K_2^*

    # (1) s_2^* = 1/s_2。右辺は K_2 だけの式（K_2^* を通さない独立な評価）。
    rep.close(s2s, _sage_const_1p0  / s2, "[K2=%.6f] s_2^* = 1/s_2" % K2)
    # (2) c_2^* = c_2/s_2 = coth(2K_2)。
    rep.close(c2s, c2 / s2, "[K2=%.6f] c_2^* = c_2/s_2" % K2)
    rep.close(c2s, _sage_const_1p0  / np.tanh(_sage_const_2  * K2), "[K2=%.6f] c_2^* = coth(2K_2)" % K2)
    # (3) 上の 2 つの帰結としての c_2^* = s_2^* c_2。
    rep.close(c2s, s2s * c2, "[K2=%.6f] c_2^* = s_2^* c_2" % K2)

    # 双対関係の定義的な言い換え: sinh(2K_2) sinh(2K_2^*) = 1。
    rep.close(s2 * s2s, _sage_const_1p0 , "[K2=%.6f] sinh 2K_2 sinh 2K_2^* = 1" % K2)
    # cosh^2 - sinh^2 = 1（K_2^* が実数であることの確認も兼ねる）。
    rep.close(c2s * c2s - s2s * s2s, _sage_const_1p0 , "[K2=%.6f] (c_2^*)^2 - (s_2^*)^2 = 1" % K2)
    rep.truth(abs(complex(K2s).imag) == _sage_const_0p0  and complex(K2s).real > _sage_const_0p0 ,
              "[K2=%.6f] K_2^* in R_{>0}" % K2)

rep.finish()

